        },
        {
            code: "RegExp('.', 'z');",
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid flags supplied to RegExp constructor 'z'" },
                type: "CallExpression"
            }]
        },
        {
            code: "RegExp('.', 'a');",
            options: [{}],
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid flags supplied to RegExp constructor 'a'" },
                type: "CallExpression"
            }]
        },
        {
            code: "new RegExp('.', 'a');",
            options: [{ allowConstructorFlags: [] }],
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid flags supplied to RegExp constructor 'a'" },
                type: "NewExpression"
            }]
        },
        {
            code: "new RegExp('.', 'z');",
            options: [{ allowConstructorFlags: ["a"] }],
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid flags supplied to RegExp constructor 'z'" },
                type: "NewExpression"
            }]
        },
        {
            code: "RegExp('.', 'a');",
            options: [{ allowConstructorFlags: ["A"] }],
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid flags supplied to RegExp constructor 'a'" },
                type: "CallExpression"
            }]
        },
        {
            code: "RegExp('.', 'A');",
            options: [{ allowConstructorFlags: ["a"] }],
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid flags supplied to RegExp constructor 'A'" },
                type: "CallExpression"
            }]
        },
        {
            code: "new RegExp('.', 'az');",
            options: [{ allowConstructorFlags: ["z"] }],
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid flags supplied to RegExp constructor 'a'" },
                type: "NewExpression"
            }]
        },
        {
            code: "new RegExp(')');",
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid regular expression: /)/: Unmatched ')'" },
                type: "NewExpression"
            }]
        },
        {
            code: String.raw`new RegExp('\\a', 'u');`,
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid regular expression: /\\a/u: Invalid escape" },
                type: "NewExpression"
            }]
        },
        {
            code: String.raw`new RegExp('\\a', 'u');`,
            options: [{ allowConstructorFlags: ["u"] }],
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid regular expression: /\\a/u: Invalid escape" },
                type: "NewExpression"
            }]
        },
        {
            code: String.raw`RegExp('\\u{0}*');`,
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid regular expression: /\\u{0}*/: Nothing to repeat" },
                type: "CallExpression"
            }]
        },
        {
            code: String.raw`new RegExp('\\u{0}*');`,
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid regular expression: /\\u{0}*/: Nothing to repeat" },
                type: "NewExpression"
            }]
        },
        {
            code: String.raw`new RegExp('\\u{0}*', '');`,
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid regular expression: /\\u{0}*/: Nothing to repeat" },
                type: "NewExpression"
            }]
        },
        {
            code: String.raw`new RegExp('\\u{0}*', 'a');`,
            options: [{ allowConstructorFlags: ["a"] }],
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid regular expression: /\\u{0}*/: Nothing to repeat" },
                type: "NewExpression"
            }]
        },
        {
            code: String.raw`RegExp('\\u{0}*');`,
            options: [{ allowConstructorFlags: ["a"] }],
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid regular expression: /\\u{0}*/: Nothing to repeat" },
                type: "CallExpression"
            }]
        },

        // https://github.com/eslint/eslint/issues/10861
        {
            code: String.raw`new RegExp('\\');`,
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid regular expression: /\\/: \\ at end of pattern" },
                type: "NewExpression"
            }]
        },

        // https://github.com/eslint/eslint/issues/16573
        {
            code: "RegExp(')' + '', 'a');",
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid flags supplied to RegExp constructor 'a'" },
                type: "CallExpression"
            }]
        },
        {
            code: "new RegExp('.' + '', 'az');",
            options: [{ allowConstructorFlags: ["z"] }],
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid flags supplied to RegExp constructor 'a'" },
                type: "NewExpression"
            }]
        },
        {
            code: "new RegExp(pattern, 'az');",
            options: [{ allowConstructorFlags: ["a"] }],
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid flags supplied to RegExp constructor 'z'" },
                type: "NewExpression"
            }]
        },

        // ES2024
        {
            code: "new RegExp('[[]', 'v');",
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid regular expression: /[[]/v: Unterminated character class" },
                type: "NewExpression"
            }]
        },
        {
            code: "new RegExp('.', 'uv');",
            errors: [{
                messageId: "regexMessage",
                data: { message: "Regex 'u' and 'v' flags cannot be used together" },
                type: "NewExpression"
            }]
        },
        {
            code: "new RegExp(pattern, 'uv');",
            errors: [{
                messageId: "regexMessage",
                data: { message: "Regex 'u' and 'v' flags cannot be used together" },
                type: "NewExpression"
            }]
        },
        {
            code: "new RegExp('[A--B]' /* valid only with `v` flag */, 'u')",
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid regular expression: /[A--B]/u: Range out of order in character class" },
                type: "NewExpression"
            }]
        },
        {
            code: "new RegExp('[[]\\\\u{0}*' /* valid only with `u` flag */, 'v')",
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid regular expression: /[[]\\u{0}*/v: Unterminated character class" },
                type: "NewExpression"
            }]
        },

        // ES2025
        {
            code: "new RegExp('(?<k>a)(?<k>b)')",
            errors: [{
                messageId: "regexMessage",
                data: { message: "Invalid regular expression: /(?<k>a)(?<k>b)/: Duplicate capture group name" },
                type: "NewExpression"
            }]
        }
    ]
});

/**
 * @fileoverview Tests for the no-useless-backreference rule
 * @author Milos Djermanovic
 */

"use strict";

//------------------------------------------------------------------------------
// Requirements
//------------------------------------------------------------------------------

const rule = require("../../../lib/rules/no-useless-backreference");
const RuleTester = require("../../../lib/rule-tester/rule-tester");

//------------------------------------------------------------------------------
// Tests
//------------------------------------------------------------------------------

const ruleTester = new RuleTester({ languageOptions: { ecmaVersion: 2025, sourceType: "script" } });

ruleTester.run("no-useless-backreference", rule, {
    valid: [

        // not a regular expression
        String.raw`'\1(a)'`,
        String.raw`regExp('\\1(a)')`,
        String.raw`new Regexp('\\1(a)', 'u')`,
        String.raw`RegExp.foo('\\1(a)', 'u')`,
        String.raw`new foo.RegExp('\\1(a)')`,

        // unknown pattern
        String.raw`RegExp(p)`,
        String.raw`new RegExp(p, 'u')`,
        String.raw`RegExp('\\1(a)' + suffix)`,
        "new RegExp(`${prefix}\\\\1(a)`)",

        // not the global RegExp
        String.raw`let RegExp; new RegExp('\\1(a)');`,
        String.raw`function foo() { var RegExp; RegExp('\\1(a)', 'u'); }`,
        String.raw`function foo(RegExp) { new RegExp('\\1(a)'); }`,
        String.raw`if (foo) { const RegExp = bar; RegExp('\\1(a)'); }`,
        String.raw`/* globals RegExp:off */ new RegExp('\\1(a)');`,
        {
            code: String.raw`RegExp('\\1(a)');`,
            languageOptions: {
                globals: { RegExp: "off" }
            }
        },

        // no capturing groups
        String.raw`/(?:)/`,
        String.raw`/(?:a)/`,
        String.raw`new RegExp('')`,
        String.raw`RegExp('(?:a)|(?:b)*')`,
        String.raw`/^ab|[cd].\n$/`,

        // no backreferences
        String.raw`/(a)/`,
        String.raw`RegExp('(a)|(b)')`,
        String.raw`new RegExp('\\n\\d(a)')`,
        String.raw`/\0(a)/`,
        String.raw`/\0(a)/u`,
        String.raw`/(?<=(a))(b)(?=(c))/`,
        String.raw`/(?<!(a))(b)(?!(c))/`,
        String.raw`/(?<foo>a)/`,

        // not really a backreference
        String.raw`RegExp('\1(a)')`, // string octal escape
        String.raw`RegExp('\\\\1(a)')`, // escaped backslash
        String.raw`/\\1(a)/`, // // escaped backslash
        String.raw`/\1/`, // group 1 doesn't exist, this is a regex octal escape
        String.raw`/^\1$/`, // group 1 doesn't exist, this is a regex octal escape
        String.raw`/\2(a)/`, // group 2 doesn't exist, this is a regex octal escape
        String.raw`/\1(?:a)/`, // group 1 doesn't exist, this is a regex octal escape
        String.raw`/\1(?=a)/`, // group 1 doesn't exist, this is a regex octal escape
        String.raw`/\1(?!a)/`, // group 1 doesn't exist, this is a regex octal escape
        String.raw`/^[\1](a)$/`, // \N in a character class is a regex octal escape
        String.raw`new RegExp('[\\1](a)')`, // \N in a character class is a regex octal escape
        String.raw`/\11(a)/`, // regex octal escape \11, regex matches "\x09a"
        String.raw`/\k<foo>(a)/`, // without the 'u' flag and any named groups this isn't a syntax error, matches "k<foo>a"
        String.raw`/^(a)\1\2$/`, // \1 is a backreference, \2 is an octal escape sequence.

        // Valid backreferences: correct position, after the group
        String.raw`/(a)\1/`,
        String.raw`/(a).\1/`,
        String.raw`RegExp('(a)\\1(b)')`,
        String.raw`/(a)(b)\2(c)/`,
        String.raw`/(?<foo>a)\k<foo>/`,
        String.raw`new RegExp('(.)\\1')`,
        String.raw`RegExp('(a)\\1(?:b)')`,
        String.raw`/(a)b\1/`,
        String.raw`/((a)\2)/`,
        String.raw`/((a)b\2c)/`,
        String.raw`/^(?:(a)\1)$/`,
        String.raw`/^((a)\2)$/`,
        String.raw`/^(((a)\3))|b$/`,
        String.raw`/a(?<foo>(.)b\2)/`,
        String.raw`/(a)?(b)*(\1)(c)/`,
        String.raw`/(a)?(b)*(\2)(c)/`,
        String.raw`/(?<=(a))b\1/`,
        String.raw`/(?<=(?=(a)\1))b/`,

        // Valid backreferences: correct position before the group when they're both in the same lookbehind
        String.raw`/(?<!\1(a))b/`,
        String.raw`/(?<=\1(a))b/`,
        String.raw`/(?<!\1.(a))b/`,
